CNAEventSingleBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "CNAEventSingleBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "CNA",
                name = "CNAEventSingle",
                version = c(1,1,0),
                options = options,
                results = CNAEventSingleResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

